  loader: () => fetchPosts(),
  errorComponent: ({ error, reset }) => {
    const router = useRouter()

    return (
      <div>
        {error.message}
        <button
          onClick={() => {
            // 라우트를 무효화해 loader를 다시 로드하고, error boundary도 재설정돼요
